Ext._define('common.document_access.allowedlistitem.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'common.document_access.allowedlistitem.Window',

    configOrderToolBar: ['add', 'revoke', '-', '->', '-', 'active'],

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Descricao', dataIndex: 'unicode', width: 150, hidden: true},
                    {header: 'Controle', dataIndex: 'control_unicode', width: 120, hidden: true},
                    {header: 'Pessoa', dataIndex: 'person_unicode', width: 220},
                    {header: 'Autorizado por', dataIndex: 'granted_by_unicode', width: 220},
                    {header: 'Autorizado em', dataIndex: 'granted_at', width: 110, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                    {header: 'Revogado por', dataIndex: 'revoked_by_unicode', width: 220},
                    {header: 'Revogado em', dataIndex: 'revoked_at', id: 'autoExpandColumn', renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')}
                ]
            );

        return this._columnModel;
    },

    revokeAction: function(selections) {
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Processando...'});
        var rest = this.factoryRestful();

        mask.show();
        rest.revoke(
            selections.map(function(row) { return row.get('pk');}),
            {
                scope: this,
                fn: function(obj) {
                    Ext.Msg.show({
                        title: 'Revogação',
                        icon: obj.success ? Ext.Msg.INFO : Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: obj.message,
                        width: 350
                    });
                }
            },
            {
                scope: this,
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Revogação',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: message,
                        width: 350
                    });
                }
            },
            {
                scope: this,
                fn: function() {
                    mask.hide();
                    this.getStore().reload();
                }
            }
        );
    },

    getActiveAction: function(cfg) {
        if(!this._activeAction) {
            this._activeAction = Ext._create('Ext.form.Checkbox', {
                name: 'active',
                allowBlank: true,
                checked: true,
                boxLabel: 'Exibir Inativos'
            });

            this._activeAction.on({
                scope: this,
                check: function(checked) {
                    if(checked.checked) {
                        // Exibir Inativos
                        this.removeFilterProperty('revoked_at', 100, false);
                        this.getStore().reload();
                    }
                    else {
                        // Exibir apenas ativos
                        this.setFilterProperty('revoked_at', null, 100);
                        this.getStore().reload();
                    }
                }
            });

        }

        return this._activeAction;
    },

    getRevokeAction: function (cfg) {
        if (!this._revokeAction) {
            this._revokeAction = Ext._create('Ext.Button', {
                text: 'Revogar',
                iconCls: 'icon-document_access icon-document_access-revoke',
                tooltip: 'Revogar credenciais da lista.',
                scope: this,
                handler: function () {
                    var selections = this.getSelectionModel().getSelections();

                    if (selections.length > 0) {
                        Ext.Msg.show({
                            title: 'Confirmação',
                            icon: Ext.Msg.QUESTION,
                            buttons: Ext.Msg.YESNO,
                            msg: 'Deseja revogar as credenciais selecionadas?',
                            scope: this,
                            fn: function(btn) {
                                if (btn == "no") return;
                                this.revokeAction(selections);
                            }
                        });
                    } else {
                        Ext.Msg.show({
                            title: 'Revogação',
                            msg: 'Selecione ao menos uma credencial para ser revogada.',
                            icon: Ext.Msg.WARNING,
                            buttons: Ext.Msg.OK,
                            width: 350
                        });
                    }
                }
            });
        }
        return this._revokeAction;
    },
});

core.RestfulGrid.register(
    'common.document_access.allowedlistitem.Restful',
    'common.document_access.allowedlistitem.Grid'
);
